-- FILTER: several conditional counts in one pass.
SELECT run_id,
       count(*) FILTER (WHERE kind = 'tool') AS tool_steps,
       count(*) FILTER (WHERE kind = 'llm')  AS llm_steps
FROM steps
WHERE run_id IN (1, 2, 3)
GROUP BY run_id
ORDER BY run_id;

